local dir=debug.getinfo(1,'S').source:sub(2):match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local c=require('common');local root=dir:gsub('[/\\]tools[/\\]selective_lockstep$','');package.path=root..'/?.lua;'..package.path;local json=require('tools.lua.lib.json');local o=c.options(arg);local samples=assert(o.positional[1],'samples required');local f=assert(io.open(samples,'r'));local rows={};for line in f:lines()do if line:match('%S')then table.insert(rows,json.decode(line))end end;f:close();assert(#rows>0,'samples must not be empty');local metrics={};local function percentile(v,fraction)table.sort(v);return v[math.min(#v,math.floor((#v-1)*fraction)+1)]end;for _,key in ipairs({'cpu_percent','memory_bytes','bytes_per_player_second','authoritative_tick_us'})do local values={};local sum=0;for _,row in ipairs(rows)do if row[key]~=nil then local value=tonumber(row[key]);table.insert(values,value);sum=sum+value end end;if #values>0 then metrics[key]={mean=sum/#values,p99=percentile(values,0.99),max=math.max(table.unpack(values))}end end;c.write_result(o.output,{samples_sha256=c.sha256_file(samples),sample_count=#rows,metrics=metrics})
